from importlib.machinery import SourceFileLoader
from pathlib import Path
p=Path(__file__).parent;m=SourceFileLoader('tle',str(p/'author-helper.py')).load_module()
m.lesson(17,'Pagkalkula ng series at parallel circuits','Kunin ang equivalent resistance, boltahe, at current sa ideal na DC resistance circuit na series o parallel.',[
('Saan dumaraan ang parehong dami','Kapag dalawang resistor ay series sa iisang landas, parehong current ang dumaraan sa dalawa. Equivalent resistance ayR=R1+R2,at boltahe ng bawat isa ayV1=IR1,V2=IR2. Boltahe ng supply ang suma ng dalawa.\nSa parallel, parehong dalawang punto ang nakakabit sa magkabilang dulo kaya pareho ang boltahe ng bawat resistor. Branch currents ayI1=V/R1,I2=V/R2,at suma ang kabuuang current. Para sa dalawa,R=R1R2/(R1+R2);kung positibo ang resistances,mas maliit ito sa mas maliit na resistor.'),
('Halimbawa ng series','Kalkulahin ang1 kΩat2 kΩna series sa ideal12 VDCsupply. Kabuuan3 kΩ=3000 Ω,current12÷3000=0.004 A=4 mA. Ang1 kΩay4 V,ang2 kΩay8 V;maititiyak na4+8=12 V. Mas malaking boltahe ang bahagi ng mas malaking resistance.'),
('Paghahambing sa parallel','Kung parehong1 kΩat2 kΩay parallel sa12 V,12 mAat6 mAang currents,kabuuang18 mA. Equivalent(1000×2000)/(1000+2000)=humigit-kumulang666.7 Ω. Kahit parehong piyesa,malaki ang pagbabago sa total current mula series. Ideal na kalkulasyon ang mga ito;sa aktuwal,tiyakin ang supply capacity,rating,init,at proteksiyon.')],['Resistance na kumakatawan sa buong maraming resistor bilang isa.','Paghahati ng boltahe sa mga bahaging series.','Paghahati ng current sa mga parallel branch.','Nakahating landas ng circuit.'],'Gabay na30minuto:3pagbalik-aral,10teksto,7paghahambing,7ibang kondisyon,3paglalagom.\nPagsulat:Sa6 V,gamit ang dalawang1 kΩ,kunin sa series at parallel ang equivalent resistance,total current,at boltahe ng bawat resistor. Isulat ang unit conversion at pag-check.\nSariling pagsusuri:Series2 kΩ・3 mA・bawat3 V;parallel500 Ω・12 mA・bawat6 Vba?',['Huwag gamitin ang pangkalkulang circuit bilang utos na baguhin ang wiring ng tunay na kagamitan.','Magpalit ng koneksiyon nang walang kuryente;kahit pang-edukasyon,tiyakin muna ng tagapagturo at suriin ang rating.'],'Series:parehong current;parallel:parehong boltahe. Nagbabago ang total current at init ayon sa koneksiyon.')
m.lesson(18,'Pag-unawa sa direksiyon ng diode at rectification','Ihiwalay ang anode,cathode,at forward direction at ipaliwanag sa salita ang rectification.',[
('Dalawang terminal at direksiyon','Ang diode ay semiconductor na may anodeAat cathodeK. Sa batayang paliwanag,forward ang mula anode patungong cathode;ang kabaligtaran ay mas mahirap daluyan. Huwag ituring na pareho kahit baligtad ang kabit dahil lamang dalawang wire ang terminal.\nMay kondisyon ang tunay na piyesa tulad ng forward voltage,allowable current,at reverse withstand voltage. Huwag tiyaking laging ganap na zero ang reverse current;gamitin sa espesipikasyon. Magkaiba rin ang nilalayong trabaho ayon sa uri,gaya ng Zener diode.'),
('Rectification at pagsusuri ng kabit','Paulit-ulit na bumabaligtad ang boltahe saAC. Gamit ang direksiyon ng diode,maaaring kumuha ng current para sa isang direksiyon;ito ang batayan ng rectification. Hindi agad palaging patag at constantDCang nakuhang waveform.\nSa pagkabit,itugma angA/Ksa circuit,polarity sa piyesa,at markang nasa board. Tingnan sa datasheet ang kahulugan ng band o marka;huwag magpasya dahil magkahawig ang hugis. Kapag hindi tugma ang polarity,i-hold at tiyakin bago lagyan ng kuryente.'),
('Pagpapaliwanag sa pang-aral na operasyon','Sa idealisadong iisang diode,kung isang direksiyon lamang ngACang nakakadaan,may bahagi ng output na dumadaloy at bahaging hindi. Kapag binaligtad,baligtad din ang panig na dumaraan. Para ito sa pag-unawa ng direksiyon,hindi pamamaraan ng direktang pagkonekta saACsupply. Kailangan din ang rating at ibang piyesa sa tunay na rectifier circuit.')],['Direksiyong mas madaling daluyan ng diode.','Kabaligtaran ng forward direction.','Pag-aayos sa direksiyon ng current.','Limitasyon ng boltahe na kayang tiisin sa takdang kondisyon.'],'Gabay na30minuto:3pagbalik-aral,10teksto,7direksiyon,7pagtutugma,3paglalagom.\nPagsulat:Ipaliwanag angA,K,at forward. Magbigay ng tatlong susuriin kung hindi tugma ang polarity sa circuit at board. Ipaliwanag ang kakulangan ng “laging patag naDCkapag na-rectify.”\nSariling pagsusuri:Naihihiwalay ba ang direksiyon at rating at napag-iisipan ang output na may ripple?',['Huwag direktang ikonekta ang piyesa sa householdACsupply para mag-eksperimento sa polarity.','Huwag subukan sa pagpapakuryente ang hindi alam na polarity o rating;tiyakin sa dokumento at nakatalaga.'],'May direksiyon ang diode. Ihiwalay ang batayang rectification,direksiyon ng kabit,at rating ng tunay na piyesa.')
m.lesson(19,'Paghahanda upang maprotektahan sa static electricity ang electronics','Unawain ang static damage at tiyakin sa paghahanda ang mesa,damit,at pamamahala ng piyesa.',[
('Pag-iwas sa hindi nakikitang pinsala','Maaaring magbago ang katangian o masira angICat ibang electronic component dahil sa static. Ang hindi pagkaramdam ng discharge at normal na hitsura lamang ay hindi garantiya na walang pinsala. Ihanda ang proteksiyon bago buksan ang packaging,sa halip na magsuri lamang pagkatapos.\nHindi sapat ang iisang hakbang sa mesa,mat,damit,sahig,o sapatos. Gamitin ang itinakdang kombinasyon at paraan ng pag-check at tiyaking maayos ang kagamitan. Kailangang matugunan pareho ang static control gamit ang conductive materials at proteksiyon ng tao laban sa pagkakuryente.'),
('Pagtutugma ng piyesa at kapaligiran','Bago magtrabaho,tiyakin ang part number,dami,pagkabulok,o pagkasira ng mga piyesa at materyal. Kilalanin ayon sa uri at maglaan ng espasyo at ilaw. Huwag maglagay ng hindi kaugnay na packaging o basura sa static-controlled work surface.\nGamitin din ang itinakdang static-protective packaging sa transportasyon at imbakan. Ang pagkakaroon lamang ng bag ay hindi nangangahulugang pareho ang performance. Kung may hindi malinaw,itanong bago buksan o ilipat. Huwag magsimula habang may hindi pa naiintindihan sa procedure.'),
('Halimbawa ng kulang na paghahanda','Bago assembly,nasa ordinaryong malinaw na bag angICat walang rekord ng pag-check sa itinakdang mat. I-hold muna ang pagbukas at itugma sa responsable ang packaging specification at rekord. Huwag basta magkabit ng metal wire at isiping sapat na;hawakan lamang kapag handa ang aprubadong work environment. Huwag laktawan ang procedure dahil malinis ang itsura.')],['Penomenong dulot ng charge na naipon sa bagay.','Pagkasira ng piyesa dahil sa static discharge at katulad nito.','Kondisyong may electric charge ang bagay.','Pagpapakilala upang maihiwalay sa iba.'],'Gabay na30minuto:3pagbalik-aral,10teksto,7kulang na paghahanda,7start checklist,3paglalagom.\nPagsulat:Gumawa ng checklist na may mesa,damit,piyesa,packaging,ilaw,at procedure. Ipaliwanag saJapaneseang susuriin bago buksan angICna nasa ordinaryong bag.\nSariling pagsusuri:Hindi ba batayan ng kaligtasan ang hindi pagkaramdam ng static at parehong tinitiyak ang aprubadong proteksiyon at pag-iwas sa pagkakuryente?',['Huwag basta ikonekta ang katawan o mesa sa power equipment bilang static control.','Iangkop ang PPEsa panganib. Huwag basta magrekomenda ng guwantes na maaaring mahila sa umiikot na bahagi.'],'Ihanda ang static control bago buksan ang piyesa. Huwag umasa sa isang gamit lamang;tiyakin ang itinakdang kapaligiran at kaligtasan.')
m.lesson(20,'Pag-unawa saANDatORng sequence control','Gumawa ng talahanayan ng binary input/output at ipaliwanag ang pagkakaiba ngAND,OR,NOT.',[
('Ihiwalay ang pagkakasunod at kondisyon','Ang sequence control ay pagpapatakbo sa bawat yugto ayon sa takdang ayos o pamamaraan. Maaaring kombinasyon ng relay at ibang piyesa o programangPLC. Upang maunawaan ang aktuwal na operasyon,ihiwalay kung kailan ano ang mangyayari at kung anong kondisyon ang naglalabas ng output.\nDito,input0ayoffat1ayonpara sa pang-aral na indicator. AND:output1lamang kung lahat1;OR:output1kung kahit isa1;NOT:baligtad na input. Hindi “isa lamang” angOR;kapag parehong1,output1rin.'),
('Pagtiyak sa apat na kombinasyon','Sa inputA,Bna00,01,10,11,ANDoutputs ay0,0,0,1atORay0,1,1,1. SaNOTofA,A=0ayoutput1,A=1ayoutput0. Sa table,mas madaling makita ang maling pakahulugan sa pang-araw-araw na “o.”\nSa batayang a-contact na nagsasara kapag inputon,series contacts angANDatparallel angOR. Ngunit lohika lamang ito;hindi nito ginagawang sapat ang design ng safety circuit. Hiwalay na suriin ang kilos sa pagkasira at safety standards.'),
('Pagbasa ng kondisyon ng indicator','Kung ang lampLaydapat umilaw kapag “parehongonangAatB,”ANDito. SaA=1,B=0,hindi iilaw;sa parehong1,iilaw. Kung “kahit isa saAatBayon,”ORito at iilaw kahitA=1,B=0. Kahit dalawang input pa rin,nagbabago ang output kapag binago ang nakasulat na kondisyon.')],['ANDna totoo kapag lahat ng kondisyon ay totoo.','ORna totoo kapag kahit isang kondisyon ay totoo.','NOTna nagpapalit ng0at1.','Signal na ibinibigay sa control.'],'Gabay na30minuto:3pagbalik-aral,10teksto,7operation table,7pagsulat ng kondisyon,3paglalagom.\nPagsulat:Gumawa ngANDatORoutput table para sa apat na kombinasyon ngA,B. Ihambing saA=0,B=1. Ipaliwanag saJapaneseang “kahit isa” at “pareho.”\nSariling pagsusuri:1rin ba angORsa11at hindi ginagamit ang lohika lamang upang patunayang ligtas ang circuit?',['Huwag basta baguhin ang interlock o safety circuit ng tunay na makina upang umayon sa pang-aral na lohika.','Subukan sa aprubadong materyal at pamamaraan;huwag gamitin ang makinang may tao sa danger zone.'],'AND:lahat;OR:kahit isa;NOT:pagbaligtad. Magkaiba ang kalkulasyon ng lohika at katumpakan ng safety circuit.')
